new:
/* Quiet neutrals + one refined accent */
--color-ink: #0a0a0a;
--color-paper: #fafafa;
--color-brand: #b08d57;

/*
 * The store's fixed black chrome: the announcement bar, the navbar, the
 * footer and the notifications header stay black with white writing in
 * EVERY design. They are deliberately not linked to --background/
 * --foreground, so picking a light or dark theme can never wash them out.
 */
--color-chrome: #0a0a0a;
--color-chrome-foreground: #fafafa;
--color-chrome-muted: oklch(1 0 0 / 58%);
--color-chrome-faint: oklch(1 0 0 / 42%);
--color-chrome-border: oklch(1 0 0 / 14%);
--color-chrome-hover: oklch(1 0 0 / 10%);
